begin;
set local lock_timeout='5s';
set local statement_timeout='15s';
lock table supabase_migrations.schema_migrations in share row exclusive mode;
do $repair$
declare original jsonb; untouched jsonb; changed integer;
begin
 if exists(select 1 from supabase_migrations.schema_migrations where version='0104') then
  raise exception '0104 already exists; history repair aborted';
 end if;
 select to_jsonb(m) into strict original from supabase_migrations.schema_migrations m
 where version='20261004082819' and name='0104_google_minimal_resident_profiles'
   and cardinality(statements)=1 and md5(array_to_string(statements,E'\n'))='2a9097c6522904020ab0da1c5f034d62';
 select jsonb_agg(to_jsonb(m) order by version) into untouched from supabase_migrations.schema_migrations m where version<>'20261004082819';
 update supabase_migrations.schema_migrations set version='0104'
 where version='20261004082819' and name='0104_google_minimal_resident_profiles';
 get diagnostics changed=row_count;
 if changed<>1 then raise exception 'Expected exactly one repaired history entry'; end if;
 if (select to_jsonb(m)-'version' from supabase_migrations.schema_migrations m where version='0104') is distinct from original-'version' then
  raise exception 'Migration metadata changed; repair rolled back';
 end if;
 if (select jsonb_agg(to_jsonb(m) order by version) from supabase_migrations.schema_migrations m where version<>'0104') is distinct from untouched then
  raise exception 'Unrelated migration history changed; repair rolled back';
 end if;
end $repair$;
commit;
select version,name,cardinality(statements) as statement_count,md5(array_to_string(statements,E'\n')) as statements_md5
from supabase_migrations.schema_migrations where version in ('0104','20261004082819');
